const incoming = $input.first().json.body;
const payload = typeof incoming === 'string' ? JSON.parse(incoming) : incoming;
const task = payload.task || {};
const now = new Date();
const due = task.dueDate ? new Date(`${task.dueDate}T23:59:59`) : null;
const days = due ? Math.ceil((due.getTime() - now.getTime()) / 86400000) : 999;
let score = task.status === 'in_progress' ? 25 : 10;
if (days < 0) score += 75; else if (days === 0) score += 65; else if (days <= 2) score += 50; else if (days <= 7) score += 25;
score = Math.min(100, score);
const priority = score >= 85 ? 'critical' : score >= 60 ? 'high' : score >= 35 ? 'medium' : 'low';
const nextSteps = [
  days < 0 ? 'Reprogramar o resolver el vencimiento hoy' : days <= 2 ? 'Reservar un bloque de trabajo hoy' : 'Definir el siguiente paso concreto',
  task.description ? 'Revisar el contexto y dividir la tarea' : 'Agregar contexto y criterio de finalización',
  'Actualizar el estado al terminar el próximo paso'
];
return [{json:{priority,score,summary:`${task.title || 'Tarea'}: prioridad ${priority} calculada por n8n`,nextSteps,notified:score>=60,processedAt:new Date().toISOString(),taskId:task.id}}];
